619	+import 'entry.dart';
620	+
621	+/// One calendar day's worth of entries — [date] is truncated to midnight
622	+/// *local* time (never UTC, never [Entry.createdAt]; Boundaries), so two
623	+/// entries whose [Entry.occurredAt] fall on the same local day always land
624	+/// in the same group regardless of the UTC offset the backend sent them in.
625	+class EntryDateGroup {
626	+  const EntryDateGroup({required this.date, required this.entries});
627	+
628	+  /// Always a `DateTime` with zeroed time-of-day fields (`DateTime(y, m,
629	+  /// d)`) — day-label formatting ("Hoje"/"Ontem"/a date string) is
630	+  /// presentation's job (Boundaries), not this pure entity's.
631	+  final DateTime date;
632	+
633	+  final List<Entry> entries;
634	+
635	+  @override
636	+  bool operator ==(Object other) =>
637	+      identical(this, other) ||
638	+      (other is EntryDateGroup &&
639	+          other.date == date &&
640	+          _listEquals(other.entries, entries));
641	+
642	+  @override
643	+  int get hashCode => Object.hash(date, Object.hashAll(entries));
644	+
645	+  @override
646	+  String toString() =>
647	+      'EntryDateGroup(date: $date, entries: ${entries.length})';
648	+}
649	+
650	+/// Groups [entries] by their [Entry.occurredAt]'s local calendar day
651	+/// (Boundaries: "never `createdAt`"). Pure Dart — no `package:flutter`
652	+/// import (RNF06), since `entries/domain` must stay flutter-free.
653	+///
654	+/// Preserves [entries]' own relative order within each group, and orders
655	+/// the returned groups by each one's first-encountered entry — callers
656	+/// (`EntriesRepository.list()`/`MeusRegistrosCubit`) always pass entries
657	+/// already newest-first, so that ordering alone already yields groups
658	+/// newest-day-first with no separate sort step needed here.
659	+///
660	+/// An empty [entries] list yields an empty list of groups (the "zero
661	+/// entries" edge case) — never a single empty group.
662	+///
663	+/// A malformed [Entry.occurredAt] (should never happen — every entry here
664	+/// was written by [EntriesRepository.create]/`list()` themselves) is
665	+/// skipped rather than thrown (RNF09), same defensive rationale
666	+/// `EntriesRepositoryImpl._offlineFallback()`'s own `DateTime.parse` guard
667	+/// already uses — one corrupt cached entry shouldn't take down the whole
668	+/// list.
669	+List<EntryDateGroup> groupEntriesByDate(List<Entry> entries) {
670	+  final entriesByDay = <DateTime, List<Entry>>{};
671	+  final dayOrder = <DateTime>[];
672	+
673	+  for (final entry in entries) {
674	+    DateTime occurredAt;
675	+    try {
676	+      occurredAt = DateTime.parse(entry.occurredAt).toLocal();
677	+    } catch (_) {
678	+      continue;
679	+    }
680	+    final day = DateTime(occurredAt.year, occurredAt.month, occurredAt.day);
681	+    final bucket = entriesByDay.putIfAbsent(day, () {
682	+      dayOrder.add(day);
683	+      return <Entry>[];
684	+    });
685	+    bucket.add(entry);
686	+  }
687	+
688	+  return [
689	+    for (final day in dayOrder)
690	+      EntryDateGroup(date: day, entries: entriesByDay[day]!),
691	+  ];
692	+}
693	+
694	+bool _listEquals(List<Entry> a, List<Entry> b) {
695	+  if (a.length != b.length) {
696	+    return false;
697	+  }
698	+  for (var i = 0; i < a.length; i++) {
699	+    if (a[i] != b[i]) {
700	+      return false;
701	+    }
702	+  }
703	+  return true;
704	+}
