1064	+
1065	+/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
1066	+/// newest-first, grouped by day, each card marked by origin. Replaces the
1067	+/// former `MeusRegistrosPlaceholderScreen`.
1068	+///
1069	+/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
1070	+/// closes it (`BlocProvider.value`, same convention
1071	+/// `AccountSettingsScreen` already uses for its own singleton cubit); only
1072	+/// this screen's own [ScrollController] is this `State`'s to dispose.
1073	+///
1074	+/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
1075	+/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
1076	+/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
1077	+/// rebuilt from scratch underneath it, so [_scrollController]'s position
1078	+/// and [cubit]'s state survive that overlay appearing with no extra code
1079	+/// needed here (Acceptance Criteria's third bullet).
1080	+class MeusRegistrosScreen extends StatefulWidget {
1081	+  const MeusRegistrosScreen({required this.cubit, super.key});
1082	+
1083	+  final MeusRegistrosCubit cubit;
1084	+
1085	+  @override
