1089	+class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
1090	+  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
1091	+  // `BootSplashScreen`.
1092	+  static const _skeletonThreshold = Duration(milliseconds: 300);
1093	+
1094	+  final ScrollController _scrollController = ScrollController();
1095	+  Timer? _skeletonTimer;
